    # Smooth isolated bitmap marks using the vertical neighborhood.
    for i, r in enumerate(rows):
        for j, c in enumerate(cols):
            neighborhood = [bits[k][j] for k in (i - 1, i, i + 1) if 0 <= k < len(rows)]
            if sum(neighborhood) > len(neighborhood) / 2:
