def transform(grid):
    out = [row[:] for row in grid]
    odd_rows = list(range(1, len(grid), 2))
    # Each repeated 3-column unit has two variable cells; replace a minority
    # value in each vertical run with the run's majority value.
    for c in (0, 1, 3, 4, 6, 7, 9, 10, 12, 13):
        vals = [grid[r][c] for r in odd_rows]
        counts = {v: vals.count(v) for v in set(vals)}
        if len(counts) == 2 and counts[0] != counts.get(grid[0][0], 0):
            majority = max(counts, key=counts.get)
            for r in odd_rows:
                out[r][c] = majority
    return out
